#include "test_support.h"
#define EVT_A UINT32_C(21)
#define EVT_B UINT32_C(22)
#define EVT_C UINT32_C(23)
static pnp_config_t classify(uint32_t type){pnp_config_t c=pass_config(1u);c.source_a.kind=(uint8_t)PNP_SRC_TYPE;c.predicate=(uint8_t)PNP_PRED_EQ;c.compare_source.kind=(uint8_t)PNP_SRC_CONSTANT;c.compare_source.immediate=type;c.emit_false=2u;return c;}
static pnp_config_t transition(uint64_t from,uint64_t to,uint32_t emit){pnp_config_t c=pass_config(emit);c.source_a.kind=(uint8_t)PNP_SRC_STATE_WORD;c.predicate=(uint8_t)PNP_PRED_EQ;c.compare_source.kind=(uint8_t)PNP_SRC_CONSTANT;c.compare_source.immediate=from;c.update_mode=(uint8_t)PNP_UPDATE_CONSTANT;c.update_constant=to;return c;}
static int run(pnp_graph_t *g,pnp_queue_t *q,pnp_graph_event_t *storage,pnp_graph_output_buffer_t *out,uint32_t type){pnp_event_t e={0};pnp_run_stats_t stats;e.type=type;pnp_queue_init(q,storage,8u);CHECK(pnp_graph_inject(q,0u,0u,&e)==PNP_OK);CHECK(pnp_graph_run(g,q,out,(pnp_run_limits_t){8u,8u},&stats)==PNP_OK);return 0;}
int main(void){pnp_node_t n[6];pnp_state_domain_t d;pnp_edge_t e[8];pnp_graph_event_t storage[8];pnp_queue_t q;pnp_graph_output_t items[4];pnp_graph_output_buffer_t out={items,4u,0u};pnp_graph_t g={n,6u,6u,e,8u,8u,&d,1u,1u};memset(n,0,sizeof(n));memset(&d,0,sizeof(d));n[0].config=classify(EVT_A);n[1].config=transition(0u,1u,1u);n[2].config=classify(EVT_B);n[3].config=transition(1u,2u,0u);n[4].config=classify(EVT_C);n[4].config.emit_false=0u;n[5].config=transition(2u,0u,1u);n[5].config.event_update_destination=(uint8_t)PNP_EVENT_DEST_METADATA;n[5].config.event_update_source=(uint8_t)PNP_EVENT_VALUE_CONSTANT;n[5].config.event_update_constant=99u;e[0]=(pnp_edge_t){0u,0u,1u,0u};e[1]=(pnp_edge_t){0u,1u,2u,0u};e[2]=(pnp_edge_t){1u,0u,PNP_EXTERNAL_NODE,0u};e[3]=(pnp_edge_t){2u,0u,3u,0u};e[4]=(pnp_edge_t){2u,1u,4u,0u};e[5]=(pnp_edge_t){3u,0u,PNP_EXTERNAL_NODE,1u};e[6]=(pnp_edge_t){4u,0u,5u,0u};e[7]=(pnp_edge_t){5u,0u,PNP_EXTERNAL_NODE,2u};CHECK(run(&g,&q,storage,&out,EVT_A)==0&&d.state.words[0]==1u&&out.count==1u);CHECK(run(&g,&q,storage,&out,EVT_B)==0&&d.state.words[0]==2u&&out.count==1u);CHECK(run(&g,&q,storage,&out,EVT_C)==0&&d.state.words[0]==0u&&out.count==2u&&out.items[1].event.fields[0]==99u);CHECK(run(&g,&q,storage,&out,99u)==0&&d.state.words[0]==0u&&out.count==2u);return 0;}
